export const meta = {
  name: 'probe',
  description: 'Two chained agents plus a global environment probe',
}
const a = await agent('Reply with exactly the word alpha and nothing else.', {label:'a'})
const b = await agent('Reply with exactly this text uppercased and nothing else: ' + a, {label:'b'})
const probe = {require: typeof require, fetch: typeof fetch, process: typeof process, Deno: typeof Deno, Bun: typeof Bun, readFile: typeof readFile, globals: Object.getOwnPropertyNames(globalThis).join(',')}
return {a, b, probe}

